window.ScripturaLexicons.BDAG_PART_0173 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-01\" data-source=\"BDAG\" data-search=\"ἰδιωτικός, ή, όν adjetivo privado; particular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰδιωτικός, ή, όν</td><td>adjetivo</td><td>privado; particular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-02\" data-source=\"BDAG\" data-search=\"ἰδού partícula demonstrativa ou apresentativa eis; olha; vê; atenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰδού</td><td>partícula demonstrativa ou apresentativa</td><td>eis; olha; vê; atenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-03\" data-source=\"BDAG\" data-search=\"Ἰδουμαία, ας, ἡ nome geográfico feminino Idumeia; Edom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰδουμαία, ας, ἡ</td><td>nome geográfico feminino</td><td>Idumeia; Edom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-04\" data-source=\"BDAG\" data-search=\"ἱδρόω verbo suar; transpirar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱδρόω</td><td>verbo</td><td>suar; transpirar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-05\" data-source=\"BDAG\" data-search=\"ἱδρύω verbo fazer sentar; estar sentado; estar estabelecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱδρύω</td><td>verbo</td><td>fazer sentar; estar sentado; estar estabelecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-06\" data-source=\"BDAG\" data-search=\"ἱδρώς, ῶτος, ὁ substantivo masculino suor; transpiração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱδρώς, ῶτος, ὁ</td><td>substantivo masculino</td><td>suor; transpiração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-07\" data-source=\"BDAG\" data-search=\"Ἰεζάβελ, ἡ nome próprio feminino indeclinável Jezabel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεζάβελ, ἡ</td><td>nome próprio feminino indeclinável</td><td>Jezabel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-08\" data-source=\"BDAG\" data-search=\"Ἰεζεκιήλ, ὁ nome próprio masculino indeclinável Ezequiel; profeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεζεκιήλ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Ezequiel; profeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-09\" data-source=\"BDAG\" data-search=\"Ἱεράπολις, εως, ἡ topônimo feminino Hierápolis; cidade da Frígia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἱεράπολις, εως, ἡ</td><td>topônimo feminino</td><td>Hierápolis; cidade da Frígia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-10\" data-source=\"BDAG\" data-search=\"Ἱεραπολίτης, ου, ὁ substantivo masculino gentílico habitante de Hierápolis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἱεραπολίτης, ου, ὁ</td><td>substantivo masculino gentílico</td><td>habitante de Hierápolis</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-11\" data-source=\"BDAG\" data-search=\"ἱερατεία, ας, ἡ substantivo feminino função sacerdotal; serviço sacerdotal; sacerdócio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερατεία, ας, ἡ</td><td>substantivo feminino</td><td>função sacerdotal; serviço sacerdotal; sacerdócio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-12\" data-source=\"BDAG\" data-search=\"ἱεράτευμα, ατος, τό substantivo neutro sacerdócio; comunidade sacerdotal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱεράτευμα, ατος, τό</td><td>substantivo neutro</td><td>sacerdócio; comunidade sacerdotal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-13\" data-source=\"BDAG\" data-search=\"ἱερατεύω verbo exercer a função sacerdotal; oficiar como sacerdote BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερατεύω</td><td>verbo</td><td>exercer a função sacerdotal; oficiar como sacerdote</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-14\" data-source=\"BDAG\" data-search=\"Ἰερεμίας, ου, ὁ nome próprio masculino Jeremias; profeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰερεμίας, ου, ὁ</td><td>nome próprio masculino</td><td>Jeremias; profeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-15\" data-source=\"BDAG\" data-search=\"ἱερεύς, έως, ὁ substantivo masculino sacerdote; ministro do culto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερεύς, έως, ὁ</td><td>substantivo masculino</td><td>sacerdote; ministro do culto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-16\" data-source=\"BDAG\" data-search=\"Ἰεριχώ, ἡ topônimo feminino indeclinável Jericó; cidade da Judeia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰεριχώ, ἡ</td><td>topônimo feminino indeclinável</td><td>Jericó; cidade da Judeia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-17\" data-source=\"BDAG\" data-search=\"ἱερόθυτος, ον adjetivo; substantivo neutro consagrado ou sacrificado à divindade; carne sacrificada a ídolos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερόθυτος, ον</td><td>adjetivo; substantivo neutro</td><td>consagrado ou sacrificado à divindade; carne sacrificada a ídolos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-18\" data-source=\"BDAG\" data-search=\"ἱερόν, οῦ, τό substantivo neutro santuário; templo; recinto sagrado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερόν, οῦ, τό</td><td>substantivo neutro</td><td>santuário; templo; recinto sagrado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-19\" data-source=\"BDAG\" data-search=\"ἱεροπρεπής, ές adjetivo reverente; venerável; condizente com o sagrado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱεροπρεπής, ές</td><td>adjetivo</td><td>reverente; venerável; condizente com o sagrado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0173-20\" data-source=\"BDAG\" data-search=\"ἱερός, ά, όν adjetivo; substantivo neutro santo; sagrado; pertencente ao templo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱερός, ά, όν</td><td>adjetivo; substantivo neutro</td><td>santo; sagrado; pertencente ao templo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0173-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰδιωτικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἴδιος</span>; Heródoto e outros; inscrições, papiros; 4Mc 4:3, 6; Fílon, In Flacc. 133 <span class=\"greek\">πράγματα</span> [em oposição a <span class=\"greek\">δημόσια</span>]; Josefo, Bell. 5, 228; Justino, A II, 3, 3.) Privado, particular: <span class=\"greek\">θλίψεις</span> <span class=\"greek\">ἰ</span>., «aflições próprias», Hv 2, 3, 1. — DELG, s.v. <span class=\"greek\">ἴδιος</span>; M-M, s.v. <span class=\"greek\">ἰδιώτης</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰδού</h1><div class=\"entry-meta\"><span>partícula demonstrativa ou apresentativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Partícula demonstrativa ou apresentativa que chama a atenção para o que vem a seguir (Sófocles e posteriores). Na realidade, é o imperativo aoristo médio de <span class=\"greek\">εἶδον</span>, <span class=\"greek\">ἰδοῦ</span>, salvo que, como partícula, recebe acento agudo (Schwyzer I 799): «vê!», «olha!», «eis!» (quanto às diferentes traduções, ver, por exemplo, E. Siegman, CBQ 9, ’47, 77s., a partir da tradução de R. Knox).</p><p class=\"entry-text\">① Elemento que desperta a atenção: «eis!», «olha!», «vê!». Como הִנֵּה, serve às vezes para dar vivacidade à narrativa.</p><p class=\"entry-text\">ⓐ Despertando a atenção dos ouvintes ou leitores (em 1Cl, 2Cl e B somente em citações do AT), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.51\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:9</a>; Jd 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:7</a>; 9:12; 11:14; Hv 1, 3, 4 e outros.</p><p class=\"entry-text\">ⓑ Introduzindo algo novo ou incomum.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Depois de genitivo absoluto, para introduzir algo novo que merece atenção especial na situação descrita de modo geral pelo genitivo absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; 2:1, 13; 9:18; 12:46; 17:5; 26:47; 28:11.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em outras construções: <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰδού</span>, «e eis»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>; 3:16; 4:11; 8:2, 24, 29, 32, 34; 9:2, 3, 20 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:20</a>, 31, 36; 2:25; 9:30, 38; 10:25 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:7</a>; 16:1; PEg2 32. Também algo inteiramente extraordinário: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀποθνῄσκοντες</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ζῶμεν</span>, «como quem está morrendo e, contudo, eis que vivemos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:24</a> (contrariamente a todas as aparências).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Introduzindo narrativas inteiras: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. No meio de um enunciado, dando-lhe ao mesmo tempo vivacidade: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:7</a>; 13:11; 20:22, 25.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Com destaque para a dimensão ou importância de algo (frequentemente omitido nas traduções, mas com alguma perda de sentido): <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἀφήκαμεν</span> <span class=\"greek\">πάντα</span>, «eis que nós deixamos tudo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:28</a>. <span class=\"greek\">ἰ</span>. <span class=\"greek\">δέκα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὀκτὼ</span> <span class=\"greek\">ἔτη</span>, «nada menos que dezoito anos!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:16</a> (cf. BGU 948, 6 <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἀσθενεῖ</span>, <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μῆνες</span>, «tua mãe está doente há treze meses»; Dt 8:4); v. 7; 15:29; 19:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:14</a>. — <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">πάσας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span>, «eis que eu estou convosco todos os dias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:20</a>; cf. 20:18; 23:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:34</a>; 6:23; 13:30 e outros.</p><p class=\"entry-text\">ⓒ Como convite a exame e consideração mais detidos: «lembrai-vos», «considerai» etc., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>; 11:8; 22:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:48</a>; 7:25; Hv 2, 3, 4. Igualmente <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">γάρ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:44</a>, 48; 2:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:11</a>; AcPl Ha 6, 19. A menção de exemplos, Tg 3:4s.; 5:4, 7, 11, também pertence aqui. Variantes em 3:3 incluem <span class=\"greek\">ἴδε</span> (ver verbete) e <span class=\"greek\">ἰδοῦ</span>; o texto tem <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span>.</p><p class=\"entry-text\">② Marcador de forte ênfase: «vê!», empregado com substantivo sem verbo finito, como as expressões coloquiais «olha só!», «quem diria!», «vejam que coisa!», «que maravilha!». Pode-se traduzir por «aqui está/estão», «ali está/estão», «aqui ou ali estava/estavam», «aí vem/veio», mas na leitura em voz alta é necessária ênfase que reproduza a nuance do original (antiga inscrição ática em Meisterhans3-Schw. p. 203 <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">χελιδῶν</span>; Epicteto 4, 11, 35; UPZ 78, 25 [159 a.C.]; LXX).</p><p class=\"entry-text\"><span class=\"greek\">καὶ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῶν</span>, «e eis que veio uma voz do céu», ou «uma voz veio diretamente do céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:17</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἄνθρωπος</span>, «e eis um homem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:10</a>. <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">φάγος</span>, «olha! Um glutão!», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:34</a>; cf. 5:12, 18; 7:37; 11:31; 13:11; 17:21a; 19:2, 20; 22:38, 47; 23:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:27</a> (W. C. van Unnik, ZNW 47, ’56, 181–91), 36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:3</a>; 21:3.</p><p class=\"entry-text\"><span class=\"greek\">ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">νυμφίος</span>, «eis o noivo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:6</a>. <span class=\"greek\">ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span>, «eis o homem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:5</a>. No Apocalipse, a fórmula <span class=\"greek\">εἶδον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰδού</span>, «vi, e eis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:1</a>; 6:2, 5, 8; 7:9; 14:14; cf. 19:11. A pessoa piedosa responde <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐγώ</span>, «eis-me aqui», à chamada divina, manifestando disposição para obedecer à ordem de Deus (1Km 3:4; TestJob 3:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:10</a>.</p><p class=\"entry-text\">(Em Mateus, <span class=\"greek\">ἰ</span>. ocorre 62 vezes; em Marcos, 7 [além das variantes em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:23</a> e 15:35]; em Lucas, 57; em João, 4 [uma delas em citação]; em Atos, 23; em Paulo, 9 [uma em citação]; em Hebreus, 4 vezes em citações; em Tiago, 6; em Judas, uma; em 1Pedro, uma em citação; em Apocalipse, 26; e não ocorre em 1–3Jo, 2Pe, Ef, Fp, Cl, 1 e 2Ts, Pastorais, Fm, Dg, Inácio nem Policarpo.) Ver Mlt. 11, com nota 1; M. Johannessohn, ZVS 64, ’37, 145–260; 66, ’39, 145–95; 67, ’40, 30–84 (especialmente sobre <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰδού</span>); P. Vannutelli, Synoptica 2, ’38, xlvi–lii: <span class=\"greek\">ἰδού</span> nos Evangelhos Sinóticos; P. Fiedler, D. Formel ‘Und Siehe’ im NT: Studien z. A. u. NT 20, ’69; A. Vargas-Machucha, (<span class=\"greek\">καὶ</span>) <span class=\"greek\">ἰδού</span> en el estilo narrativo de Mt, Biblica 50, ’69, 233–44. Ver <span class=\"greek\">ἴδε</span>. — DELG, s.v. <span class=\"greek\">ἰδεῖν</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰδουμαία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome geográfico feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Idumeia, forma helenizada (Diodoro Sículo 19, 95, 2 e outros; Apiano, Mithrid. 106 §499; LXX; Josefo) de אֱדוֹם (Edom), região montanhosa ao sul da Judeia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:8</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱδρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo imperativo <span class=\"greek\">ἱδρωσάτω</span> (ver <span class=\"greek\">ἱδρώς</span>; Homero e outros; POxy 1242, 52; 4Mc 3:8; 6:11). Suar, transpirar; figuradamente, <span class=\"greek\">ἱδρωσάτω</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλεημοσύνη</span> <span class=\"greek\">σου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖράς</span> <span class=\"greek\">σου</span>, «que tua esmola sue em tuas mãos», isto é, não concedas esmolas sem a devida ponderação, D 1:6 (citação de origem desconhecida; cf. SibOr 2, 79; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a>. — Ver <span class=\"greek\">ἐλεημοσύνη</span> 2). — DELG, s.v. <span class=\"greek\">ἱδρώω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱδρύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Particípio perfeito passivo <span class=\"greek\">ἱδρυμένος</span> (Homero e posteriores; inscrições [por exemplo IAndrosIsis, Kyme 24]; PGiss 99, 16; 4Mc 17:3; TestJob 10:1; 32:7; Fílon; Josefo, Ant. 1, 60; C. Ap. 2, 36; Justino; Atenágoras 14, 1). Na voz ativa, «fazer sentar»; nesta literatura, somente na passiva: «estar sentado», «sentar-se», «estar estabelecido». No perfeito passivo, a respeito da fé, <span class=\"greek\">ἵδρυται</span>, «está estabelecida», Dg 11:6. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱδρυμένος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τόπος</span>, «o lugar estabelecido para eles», 1Cl 44:5. — DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱδρώς, ῶτος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἱδρόω</span>; Homero e posteriores; PGM 5, 152 <span class=\"greek\">ἱ</span>. … <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆν</span>; LXX; JosAs; Fílon; Josefo, Bell. 3, 5; Ant. 7, 282.) Suor, transpiração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:44</a> (Justino, D. 103, 8. Sobre isso, L. Brun, ZNW 32, ’33, 265–76. — Suor de sangue [JosAs 4:11] como fenômeno extraordinário: Apolônio de Rodes 4, 1284, acerca de imagens; Apiano, Bell. Civ. 4, 4 §14). — <span class=\"greek\">διὰ</span> <span class=\"greek\">κόπου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱδρῶτος</span>, «com fadiga e suor» (cf. Fílon, Leg. All. 3, 251), B 10:4. R. Brown, SPSBL ’92, 158s. — B. 264; DELG, s.v. <span class=\"greek\">ἱδρώω</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεζάβελ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também <span class=\"greek\">Ἰεζαβήλ</span>; indeclinável; אִיזֶבֶל; 3Km 16:31 e outros. — Em Josefo, <span class=\"greek\">Ἰεζαβέλη</span>, <span class=\"greek\">ης</span> [Ant. 8, 356].) Jezabel, rainha de Acabe, que promoveu o culto ao Baal fenício em Israel e perseguiu os profetas de Javé (3Km 16–4Km 9), também dada à prostituição e à magia (4Km 9:22). Por isso, o nome foi aplicado a uma mulher que ameaçava o ensino ortodoxo da comunidade cristã de Tiatira, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:20</a>. E. Schürer (Weizsäcker Festschr., 1892, 39–58) considera que se refere a uma profetisa do templo da Sibila caldeia naquela cidade. Zahn, em Einl.3 II 620ss. e em seu comentário, prefere a leitura <span class=\"greek\">γυναῖκά</span> <span class=\"greek\">σου</span> e entende a mulher como esposa do bispo. — Ver Kraft, Hdb., ’74, ad loc.; sobre a suposta associação de Jezabel com feitiçaria, ver P. Duff, NTS 43, ’97, 116–33; Mussies 889–92; DDD, s.v. Jezebel. — M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεζεκιήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Indeclinável (יְחֶזְקֵאל; Justino; Melitão, HE 4, 26, 14; em Josefo, <span class=\"greek\">Ἰεζεκίηλος</span>). Ezequiel, profeta veterotestamentário (Ez 1:3), 1Cl 17:1. <span class=\"greek\">λέγει</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γραφὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰεζεκιήλ</span>, «diz a Escritura em Ezequiel», 2Cl 6:8 (quanto à citação de Ez 14:14, 16, 18, ver Knopf, Hdb., ad loc.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἱεράπολις, εως, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também <span class=\"greek\">Ἱερὰ</span> <span class=\"greek\">Πόλις</span>; B-D-F §115, 2 defendem a grafia <span class=\"greek\">Ἱερᾷ</span> <span class=\"greek\">πόλει</span>; ver Mlt-H. 278.) Hierápolis, cidade da Frígia, na Ásia Menor, junto ao rio Lico (Antígono de Caristo 174 <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἱεραπόλει</span>; SibOr 5, 318; 12, 280; Altertümer v. Hierap.: Jahrb. d. Deutsch. Arch. Inst., Ergänzungsheft 4, 1898; S. Johnson, BA 13, ’50, 12–18), Cl 4:13; ver <span class=\"greek\">νέος</span> 5 e <span class=\"greek\">Ἡλιούπολις</span>; Pápias (2 e 9). <span class=\"greek\">Παπίας</span> <span class=\"greek\">Ἱεραπόλεως</span> <span class=\"greek\">ἐπίσκοπος</span>, «Pápias, bispo de Hierápolis», Pápias (11:1); cf. (9; 12:2). — BHHW II 717s.; Kl. Pauly II 1129s.; PECS 390s. — M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἱεραπολίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Aa 1, 90, 1, variante de leitura.) Habitante de Hierápolis: <span class=\"greek\">Παπίας</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἱεραπολίτης</span>, «Pápias, o hierapolitano», Pápias (6 e 7). Ver <span class=\"greek\">Ἱεράπολις</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερατεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes seguintes; Aristóteles, Pol. 7, 8 p. 1328b, 12s.; Dionísio de Halicarnasso 2, 73; inscrições anteriores a 335 a.C. [IPriene 139, 7]; cf. OGI 90, 52; SIG, índice IV p. 390a; PTebt 298, 14; LXX; Test12Patr.) Cargo ou serviço sacerdotal: <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἱ</span>., «segundo o costume da função sacerdotal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:9</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">λαμβάνειν</span>, «receber o ofício sacerdotal» (cf. Dionísio de Halicarnasso, loc. cit. <span class=\"greek\">παραλαμβάνει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἱερατείαν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δοκιμασθείς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>. — «Sacerdócio», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:10</a>, variante de leitura. — Frisk, s.v. <span class=\"greek\">ἱερός</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱεράτευμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete seguinte; encontrado apenas no grego de autores bíblicos e de escritores deles dependentes.) Sacerdócio: <span class=\"greek\">οἰκοδομεῖσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἅγιον</span>, «ser edificados como sacerdócio santo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:5</a>; <span class=\"greek\">βασίλειον</span> <span class=\"greek\">ἱ</span>., «sacerdócio de categoria real» ou «a serviço de um rei», v. 9 (Êx 19:6; 23:22; cf. Melitão, P. 68, 494 [Cristo]). P. Dabin, Le sacerdoce royal des fidèles dans l. livres saints, ’41, 179–97; W. Arndt, CTM 19, ’48, 241–49; J. Blinzler, Episcopus [Faulhaber Festschr.], ’49, 49–65; J. Elliott, The Elect and the Holy (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.4-10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:4–10</a>), ’66; A Home for the Homeless, ’81, especialmente p. 168: <span class=\"greek\">ἱ</span>. realça a consagração do povo de Deus à <span class=\"greek\">ἀγαθοποιί̈α</span>. — Frisk, s.v. <span class=\"greek\">ἱερός</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερατεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἱερατεύσω</span>; 1º aoristo singular <span class=\"greek\">ἱεράτευσα</span>, TestLevi 12:5 (ver <span class=\"greek\">ἱερός</span> e os dois verbetes anteriores; palavra do grego tardio: Herodiano 5, 6, 3; Heliodoro 10, 40 e outros; inscrições do séc. II a.C.: OGI 90, 51 [196 a.C.]; IMagnMai 178, 6 [séc. II a.C.]; outros exemplos epigráficos em Dssm., NB 43 [BS 215s.]; PGiss 11, 10 [118 d.C.]; PKöln 81 [105/104 a.C.], acerca do sacerdócio exercido pela rainha Cleópatra; LXX; Test12Patr; Josefo, Ant. 3, 189; 15, 253; Justino, A I, 62, 2). Exercer o ofício ou desempenhar o serviço de sacerdote, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:8</a>. Com <span class=\"greek\">λειτουργεῖν</span>, 1Cl 43:4. — Frisk, s.v. <span class=\"greek\">ἱερός</span>; New Docs 4, 156 (inscrição); M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰερεμίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também <span class=\"greek\">Ἱερ</span>-; יִרְמְיָה, יִרְמְיָהוּ; LXX; ParJer; EpArist 50; Fílon, Cher. 49; Josefo, Justino, Melitão; Atenágoras 9, 1.) Jeremias, profeta da época da queda do Estado judaico: <span class=\"greek\">ῥηθὲν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">Ἰερεμίου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προφήτου</span>, «dito por intermédio do profeta Jeremias» (cf. Josefo, Ant. 11, 1; Justino, A I, 51, 8 e D. 72, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:17</a>; 27:9 (variante <span class=\"greek\">Ἰησαί̈ου</span>). Alguns conterrâneos de Jesus consideravam que ele era Jeremias retornado (ver Billerb. I 730), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:14</a>. — H. Sparks, JTS n.s. 1, ’50, 155s.; J. Carmignac, Festschrift K. Kuhn, ’71, 283–98. — TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores; acusativo -<span class=\"greek\">έαν</span> em GJs 15:2.) Sacerdote.</p><p class=\"entry-text\">ⓐ Literalmente, com foco na função cultual.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Sacerdotes greco-romanos (Demétrio: 722 Fgm. 1, 12 Jac.; Taciano 36, 1 <span class=\"greek\">Βηρωσσός</span> e outros; Atenágoras 28, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:13</a>; 1Cl 25:5. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱερεῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εἰδώλων</span>, «sacerdotes dos ídolos», B 9:6.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sacerdotes de Israel (Diodoro Sículo 40, 3, 4 e 5). Sacerdote comum: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱερεύς</span>, «o sacerdote» que oficia em determinada ocasião (Lv 13:2ss.; Justino, D. 115, 3 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:14</a>. Em outros casos, de sacerdote individual: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:5</a>; 10:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:4</a>; 10:11 (variante <span class=\"greek\">ἀρχι</span>-). No plural: Mt 12:4s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:4</a>; 17:14; 20:1, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:19</a>; 8:4, Códice D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:1</a> (variante <span class=\"greek\">ἀρχι</span>-); 6:7; Hb 7:14s., 20, 23; 9:6; GPt 7:25; B 7:4 (citação de origem desconhecida; ver Windisch, ad loc.), v. 6 (cf. Lv 16:5).</p><p class=\"entry-text\">IPhld 9:1; GJs 4:3; 6:2 (duas vezes); 8:2 (duas vezes); 10:1; 24:1 (duas vezes), 2, 4. Com <span class=\"greek\">Λευῖται</span>, «levitas», 1Cl 32:2 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:31</a> e 32: mencionados antes dos levitas como em Josefo, Ant. 11, 80s. e frequentemente em Josefo [Schmidt 358]). Com os levitas e o <span class=\"greek\">ἀρχιερεύς</span>, «sumo sacerdote», 40:5. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span>, «sacerdotes do templo», B 7:3.</p><p class=\"entry-text\">De sumo sacerdote (Diodoro Sículo 34 + 35 Fgm. 1, 3; 3Km 1:8; Br 1:7; 1Mc 15:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:27</a>, Códice D. <span class=\"greek\">Ἀαρὼν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἱερεύς</span>, «Arão, o sacerdote» (cf. Êx 35:19; Lv 13:2. — <span class=\"greek\">ἱ</span>. também designa sumos sacerdotes greco-romanos em Mayser II/2 p. 465; Apiano, Bell. Civ. 4, 134 §562 chama César, Pontifex Maximus, de <span class=\"greek\">ἱ</span>.; Sinésio, Prov. 2, 3 p. 122a), GEb 13, 75 (ver GHb 361, 7 servus sacerdotis); GJs 5:1 (duas vezes); 7:2; 8:3; 9:1 (três vezes), 2; 10:1 (três vezes); 12:1 (duas vezes); 15:2 (seguido de <span class=\"greek\">ἀρχιερεύς</span>; ver verbete; ver também H. Greeven, NTS 6, ’60, 295s.).</p><p class=\"entry-text\">ⓑ Extensão figurada de ⓐ.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De Cristo, chamado em Hebreus <span class=\"greek\">ἱερεὺς</span> (no sentido de a<span class=\"greek\">β</span>; ver 5:5s.; Justino, D. 34, 2 e outros) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">Μελχισέδεκ</span>, «para sempre segundo a ordem de Melquisedeque» (Sl 109:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:6</a>; 7:17, 21; também <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">μέγας</span>, «grande sacerdote» (1Mc 12:20; cf. Sir 50:1; Jdt 4:6, 8, 14; Fílon, Spec. Leg. 1, 161 e outros = <span class=\"greek\">ἀρχιερεύς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:21</a>. Cf. também 7:1, 3, 11; ver <span class=\"greek\">ἀρχιερεύς</span> 2a; C. Spicq, Festschrift M. Goguel, ’50, 258–69.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Dos cristãos: <span class=\"greek\">ἱερεῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «sacerdotes de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:6</a>; cf. 1:6; 5:10 (Diógenes Laércio 7, 119: segundo a escola estoica, os <span class=\"greek\">σοφοί</span>, «sábios», são os únicos sacerdotes verdadeiros). — A. Gunneweg, Leviten u. Priester, ’65; B. 1472. — Frisk, s.v. <span class=\"greek\">ἱερός</span>; M-M; EDNT; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰεριχώ, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também <span class=\"greek\">Ἱερ</span>-, <span class=\"greek\">Ἰερειχώ</span>, <span class=\"greek\">Ἱερειχώ</span>; indeclinável; יְרִיחוֹ; LXX; Justino, D. 111, 4. Sobre a palavra, ver W-S. §10, 1a. Josefo varia entre <span class=\"greek\">Ἱεριχώ</span>, genitivo -<span class=\"greek\">οῦς</span>, e <span class=\"greek\">Ἱεριχοῦς</span>, genitivo -<span class=\"greek\">οῦντος</span>; ver índice de Niese. <span class=\"greek\">Ἰεριχοῦς</span>, -<span class=\"greek\">οῦντος</span>, também em Galeno XI 693 K. e Estêvão de Bizâncio, s.v., mas Estrabão 16, 2, 41 traz <span class=\"greek\">Ἰερικοῦς</span>. Sobre a grafia, ver B-D-F §38.) Jericó, cidade da Judeia não distante da passagem do Jordão, ao norte do mar Morto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a>; 1Cl 12:2.</p><p class=\"entry-text\">Como uma estrada muito transitada levava a Jerusalém, a 150 estádios (Josefo, Bell. 4, 474), ou cerca de 30 km de distância, havia ali um posto aduaneiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:1</a>. A estrada de Jerusalém a Jericó, atravessando região montanhosa desolada (Josefo, loc. cit. <span class=\"greek\">ἔρημον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πετρῶδες</span>), era notoriamente perigosa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:30</a> (A. van Veldhuizen, TSt 25, 1907, 41–43). — E. Sellin e C. Watzinger, Jericho, 1913; Dalman, Orte3 257ss.; P. Thomsen, Jericho: Reallex. d. Vorgesch. VI 196, 153ss.; J. Pritchard, The 1951 Campaign at Herodian Jer.: BASOR n.º 123, ’51, 8–17; J. Kelso, NT Jericho: BA 14, ’51, 34–43; L. Mowry, ibid. 15, ’52, 26–42. — BHHW II 816–19; OEANE III 220–24.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερόθυτος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἱερός</span>, <span class=\"greek\">θύω</span>; Píndaro, Fgm. 66 [OxfT = 78 S-M.] chama a morte pela própria pátria de <span class=\"greek\">ἱερόθυτος</span> <span class=\"greek\">θάνατος</span>, «morte consagrada»; um dos testemunhos mais antigos da palavra; SIG 624, 43; 736, 23; PGM 4, 2899.) Dedicado ou sacrificado a uma divindade; substantivado, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «carne sacrificada aos ídolos» (Pseudo-Aristóteles, Mirabilia 123 p. 824b, 1s.; Plutarco, Mor. 729c <span class=\"greek\">ἐγεύοντο</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱεροθύτων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:28</a>. — M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Substantivação do adjetivo <span class=\"greek\">ἱερός</span>, ver verbete.) Santuário, templo (assim Heródoto e posteriores).</p><p class=\"entry-text\">ⓐ De templos greco-romanos (Diodoro Sículo 13, 7, 6 <span class=\"greek\">τ</span>. <span class=\"greek\">Διὸς</span> <span class=\"greek\">ἱερόν</span>; Apiano, Liby. 81 §383 e outros; Bel 22, Teodocião; 1Mc 10:84; Fílon, Leg. ad Gai. 139 e outros; Josefo, Ant. 18, 65; Justino, A I, 9, 5; Atenágoras 14, 2): o templo de Ártemis em Éfeso (ver o final de b, abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:27</a>.</p><p class=\"entry-text\">ⓑ Do templo de Jerusalém, incluindo todo o recinto do templo, com seus edifícios, átrios etc. (LXX; Ez 45:19; 1Cr 29:4 e muitas vezes nos apócrifos; TestSol; EpArist; Fílon, Josefo; Justino, A I, 32, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγιστον</span> <span class=\"greek\">ἱ</span>. … <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>; Políbio 16, 39, 4; Diodoro Sículo 40, 3, 3; Estrabão 16, 2, 34; OGI 598, 3; PGM 13, 233): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:6</a>; 21:23; 24:1b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:27</a>; 12:35; 13:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:46</a>; 20:1; 21:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:20</a>; 11:56; 18:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:6</a>; 25:8; Ox 840, 9.</p><p class=\"entry-text\"><span class=\"greek\">στρατηγὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἱεροῦ</span>, «capitão do templo» (Josefo, Bell. 6, 294), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:1</a>; 5:24; no plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:52</a>. <span class=\"greek\">ἀναβαίνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «subir ao templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:1</a>. <span class=\"greek\">εἰσάγειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «introduzir no templo», At 21:28s. (<span class=\"greek\">εἰς</span>)<span class=\"greek\">ελθεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «entrar no templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12a</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:11</a>, 15a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:27</a>; 19:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:8</a>; 5:21. <span class=\"greek\">εἰσιέναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «entrar no templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:3</a>; 21:26. <span class=\"greek\">εἰσπορεύεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «adentrar o templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:2b</a>. <span class=\"greek\">παραγίνεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., «chegar ao templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:2</a>. <span class=\"greek\">ἐξελθεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>., «sair do templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:1a</a>; <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:59</a>; <span class=\"greek\">ἐκπορεύεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>., «sair do templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:1</a>.</p><p class=\"entry-text\">Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:47</a>; 21:37; 22:53; 24:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:14</a>; 7:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:46</a>; 3:2a; 5:20, 25, 42; 21:27; 22:17; 24:12, 18; 26:21. <span class=\"greek\">ἔξω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>., «fora do templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:30</a>. Como lugar onde os sacerdotes trabalhavam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:5</a>. Provido de pórticos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:23</a>.</p><p class=\"entry-text\">Mesmo quando a ação acontece no Átrio dos Gentios, onde mercadores e cambistas tinham seus lugares, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12</a> (ver também vv. 14 e 15); Mc 11:15s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:45</a>; Jo 2:14s., ou no Átrio das Mulheres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:37</a>, a escolha de <span class=\"greek\">ἱ</span>. enfatiza que a cena se passa no recinto sagrado (<span class=\"greek\">τὸ</span> <span class=\"greek\">ἱ</span>., ao lado de <span class=\"greek\">ὁ</span> <span class=\"greek\">ναός</span>, «edifício do templo»: Josefo, Bell. 2, 400. Sobre a purificação do templo, ver A. Caldecott, JTS 24, 1923, 382ss.; F. Burkitt, ibid. 25, 1924, 386ss.; F. Braun, RB 38, 1929, 178–200; E. Lohmeyer, ThBl 20, ’41, 257–64. — Apiano, Bell. Civ. 2, 120 §507 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱεροῖς</span>, ladrões se abrigam em templos; Ep. 65 de Apolônio de Tiana [Filóstrato I 363, 23], o <span class=\"greek\">ἱερόν</span> de Ártemis em Éfeso como <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀποστερούντων</span> <span class=\"greek\">μυχός</span>, «esconderijo de ladrões»).</p><p class=\"entry-text\">Sobre <span class=\"greek\">τὸ</span> <span class=\"greek\">πτερύγιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>, «pináculo do templo» (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:9</a>; PEg3 8 [<span class=\"greek\">πτερύγιον</span> restaurado]), ver <span class=\"greek\">πτερύγιον</span>. Sobre <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὡραίᾳ</span> <span class=\"greek\">πύλῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>., «junto à Porta Formosa do templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:10</a>, ver <span class=\"greek\">ὡραῖος</span> 2.</p><p class=\"entry-text\">ⓒ Em sentido geral, quer se trate de culto politeísta quer monoteísta: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἐσθίειν</span>, «comer do que provém do templo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:13</a> (ver J. Moffatt, comentário). — P. Joüon, Les mots employés pour désigner ‘le temple’ dans AT, NT et Josèphe: RSR 25, ’35, 329–43; O. Wolf, D. Tempel v. Jerus., ’31; E. Lohmeyer, Kultus u. Evglm, ’42; G. May, ET 62, ’50s., 346s.; C. Kopp, The Holy Places in the Gospels (trad. R. Walls), ’63, 283–304; R. Clements, God and Temple, ’65; S. Safrai, The Temple: CRINT I/2, 865–907. — B. 1465; M-M; EDNT; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱεροπρεπής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(De <span class=\"greek\">ἱερός</span>, <span class=\"greek\">πρέπω</span>; sobre a terminação, ver DELG, s.v. <span class=\"greek\">πρέπω</span>.) Reverente, venerável (Xenofonte, Symp. 8, 40; Platão, Theag. 122d; Cássio Dio 56, 46; Luciano, Sacrif. 13; Plutarco, Lib. Educ. 14 p. 11c; 4Mc 9:25; 11:20; Fílon, Abr. 101; Decal. 60; Leg. All. 3, 204; Josefo, Ant. 11, 329), acerca da conduta das mulheres idosas da congregação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:3</a>. O sentido mais especializado «sacerdotal», «semelhante ao de um sacerdote» (assim Dibelius), derivado do emprego da palavra para descrever a conduta de um sacerdote (Michel 163, 21; IPriene 109, 216; SIG 708, 24; Fílon, Omn. Prob. Lib. 75), é menos provável aqui. — M-M; TW; Spicq; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0173-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱερός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo; substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.)</p><p class=\"entry-text\">① Referente à pureza transcendente: santo, sagrado, adjetivo (Josefo, Ant. 16, 27; 28; Justino, A I, 1, 1 <span class=\"greek\">ἱερᾷ</span> … <span class=\"greek\">συγκλήτῳ</span>; D. 52, 3 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱερῶν</span> <span class=\"greek\">σκευῶν</span> <span class=\"greek\">ἀρθέντων</span>). [<span class=\"greek\">τὰ</span>] <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">γράμματα</span> (<span class=\"greek\">γράμμα</span> 2c), «as letras ou Escrituras sagradas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:15</a>. Também <span class=\"greek\">ἱεραὶ</span> <span class=\"greek\">βίβλοι</span> (<span class=\"greek\">βίβλος</span> 1), «livros sagrados», 1Cl 43:1. <span class=\"greek\">ἱ</span>. <span class=\"greek\">γραφαί</span> (<span class=\"greek\">γραφή</span> 2b<span class=\"greek\">α</span>), «Escrituras sagradas», 45:2; 53:1. (Sobre escritos «sagrados», ver New Docs 3, 64.) <span class=\"greek\">ἱ</span>. <span class=\"greek\">κήρυγμα</span>, «proclamação sagrada», no final breve de Marcos; de Deus, <span class=\"greek\">ἱ</span>. <span class=\"greek\">χεῖρες</span>, «mãos santas», que não tocam nada profano, 1Cl 33:4; <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ἀποστόλων</span>, «dos santos apóstolos», Pápias (2:2). <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πολυτέλεια</span> <span class=\"greek\">καλὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱερᾶ</span>, Hs 1:10, variante de leitura (ver <span class=\"greek\">ἱλαρός</span>).</p><p class=\"entry-text\">② Pertencente ao templo e ao seu serviço: coisa sagrada, substantivado <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱερά</span> (Demóstenes 57, 3 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱερῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κοινῶν</span> <span class=\"greek\">μετέχειν</span>; Fílon, Spec. Leg. 3, 40; Josefo, Ant. 14, 214). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">ἐργάζεσθαι</span>, «prestar os serviços sagrados no templo» (cf. Élio Aristides 51, 66 K. = 27 p. 550 D.: <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">ποιεῖν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:13a</a>. — <span class=\"greek\">Ἱερᾷ</span> <span class=\"greek\">πόλει</span>, ver <span class=\"greek\">Ἱεράπολις</span>. — B. 1475; LfgrE, s.v. (bibliografia, col. 1139); M-M; Schmidt, Syn. IV 321–45; DELG; TW; Sv.</p></section></article>\n"};
